   387              // Copy the next 4x4 pixel block into array s.
   388              // If the width, cd.nx, or the height, cd.ny, of
   389              // the pixel data in _tmpBuffer is not divisible
   390              // by 4, then pad the data by repeating the
   391              // rightmost column and the bottom row.
   392              //
   393
   394              uint16_t* row0 = (uint16_t*) scratch;
