   396              uint16_t* row1 = row0 + nx;
   397              uint16_t* row2 = row1 + nx;
   398              uint16_t* row3 = row2 + nx;
   399
   400              if (y + 3 >= ny)
   401              {
   402                  if (y + 1 >= ny) row1 = row0;
   403                  if (y + 2 >= ny) row2 = row1;
   404
   405                  row3 = row2;
   406              }
   407
   408              for (int x = 0; x < nx; x += 4)
   409              {
   410                  uint16_t s[16];
   411
   412                  if (x + 3 >= nx)
   413                  {
   414                      int n = nx - x;
   415
   416                      for (int i = 0; i < 4; ++i)
   417                      {
   418                          int j = i;
   419                          if (j > n - 1) j = n - 1;
   420
   421                          s[i + 0]  = row0[j];
   422                          s[i + 4]  = row1[j];
   423                          s[i + 8]  = row2[j];
   424                          s[i + 12] = row3[j];
   425                      }
   426                  }
