   428                  {
   429                      memcpy (&s[0], row0, 4 * sizeof (uint16_t));
   430                      memcpy (&s[4], row1, 4 * sizeof (uint16_t));
   431                      memcpy (&s[8], row2, 4 * sizeof (uint16_t));
   432                      memcpy (&s[12], row3, 4 * sizeof (uint16_t));
   433                  }
   434
   435                  row0 += 4;
   436                  row1 += 4;
   437                  row2 += 4;
   438                  row3 += 4;
